import{_ as d,o as e,c as r,ag as o}from"./chunks/framework.DC2anBTf.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1793536832000}'),a={name:"guide/introduction.md"};function i(s,t,l,n,u,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><h2 id="为什么需要这套架构" tabindex="-1">为什么需要这套架构 <a class="header-anchor" href="#为什么需要这套架构" aria-label="Permalink to &quot;为什么需要这套架构&quot;">​</a></h2><p>uni-app x 是 DCloud 的新一代跨端方案：UTS 语言、编译期静态模型，一份代码编译为 JS（Web / 小程序）与 Kotlin / Swift 原生。性能出色——但当你想认真做一个中大型项目时，会撞上一个现实：<strong>生态默认形态是「页面堆」</strong>。请求写在页面里、状态挂在页面 data、跳转靠裸字符串路径、响应是裸 <code>UTSJSONObject</code> 下标取值。</p><p>标准 Vue3 生态那套工程化（vue-router 单路由表、pinia 插件协议、axios 封装、js-cookie 同步读取）<strong>不能直接搬过来</strong>。uni-app x 的页面是编译期静态模型，有四个根本性差异：</p><ol><li><strong>没有单路由表</strong>——页面在 <code>pages.json</code> 静态注册，编译期确定；</li><li><strong>插件协议不可靠</strong>——App 端（Kotlin）<code>app.use(pinia)</code> 实测不生效；</li><li><strong>存储全是异步</strong>——没有同步 cookie 可用；</li><li><strong>名义类型系统</strong>——Kotlin 端类型不兼容不是报错，而是 cast 崩溃。</li></ol><p>这意味着工程化必须在底座约束下<strong>重新设计</strong>。本模板就是这套设计的完整落地。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><ul><li><strong>分层完备</strong>：api / stores / router / utils / pages 各司其职、类型契约清晰、装配点唯一；</li><li><strong>鉴权开箱即用</strong>：登录闭环、全局守卫、冷启动竞态消除全部内置；</li><li><strong>可复制</strong>：每个架构决策都有明确的判据与实测依据，接入真实后端只需改一处配置。</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>框架</td><td>uni-app x（HBuilderX 5.34+，VDOM 模式，vapor: true）</td></tr><tr><td>语言</td><td>UTS（编译到 JS / Kotlin / Swift）</td></tr><tr><td>UI 范式</td><td>Vue3 组合式 API，uvue 页面</td></tr><tr><td>状态管理</td><td>ux-pinia（class 式 store，免挂载）</td></tr><tr><td>路由</td><td>ux-router（vue-router 风格 API + 全局守卫）</td></tr><tr><td>网络</td><td>mx-request（拦截器体系）</td></tr><tr><td>持久化</td><td>ux-storage（异步）</td></tr><tr><td>反馈</td><td>ux-utils（toast / modal 全端自绘）</td></tr><tr><td>UI 组件库</td><td>m-ui-x（11 个基础组件，easycom 零注册）</td></tr></tbody></table><h2 id="分层与插件承载关系" tabindex="-1">分层与插件承载关系 <a class="header-anchor" href="#分层与插件承载关系" aria-label="Permalink to &quot;分层与插件承载关系&quot;">​</a></h2><p>各层职责单一、依赖单向：</p><table tabindex="0"><thead><tr><th>分层</th><th>位置</th><th>承载插件</th></tr></thead><tbody><tr><td>网络层（全局配置 + 双拦截器）</td><td><code>utils/request.uts</code></td><td>mx-request</td></tr><tr><td>接口层（领域函数 + DTO 还原）</td><td><code>api/*.uts</code></td><td>mx-request</td></tr><tr><td>凭证读写（token 同步读体验）</td><td><code>utils/auth.uts</code></td><td>ux-storage</td></tr><tr><td>状态层（业务状态与动作）</td><td><code>stores/modules/*.uts</code></td><td>ux-pinia</td></tr><tr><td>路由层（命名路由 + 守卫链）</td><td><code>router/index.uts</code></td><td>ux-router</td></tr><tr><td>全局守卫（鉴权重定向）</td><td><code>router/permission.uts</code></td><td>ux-router guard</td></tr><tr><td>配置层（全局唯一配置源）</td><td><code>config/index.uts</code></td><td>—</td></tr><tr><td>视图层（静态注册页面）</td><td><code>pages/</code></td><td>uni-app x 约定</td></tr></tbody></table><p>两条底座事实需要了解：</p><ul><li>uni-app x 无全局 layout 机制，页面结构由各页面自持；</li><li>setup 式 store 中 <code>computed</code> 即 getter 的老观念已过时——ux-pinia 0.2.0 为 class 式 store，派生值用 class getter。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./getting-started.html">快速开始</a>：克隆、配置、跑起来；</li><li><a href="./architecture.html">架构设计</a>：目录结构、调用链与装配范式；</li><li><a href="./conventions.html">工程约定</a>：类型组织、UTS 红线与各域细则。</li></ul>',17)])])}const g=d(a,[["render",i]]);export{p as __pageData,g as default};
